<?php
namespace Modules\Representation\Http\Controllers;
use App\Mail\TemplateMail;
use App\Support\Organization;
use App\Http\Controllers\Controller; use Modules\Representation\Models\{LegalRepresentation,LegalRepresentationAnnouncement,LegalRepresentationCandidate,LegalRepresentationVolunteer}; use Modules\Representation\Support\SendsAnnouncements; use App\Services\MailgunMailingList; use App\Support\HtmlSanitizer; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Auth,Mail};
class LegalRepresentationController extends Controller {
 use SendsAnnouncements;
 public function index(){return view('representation::index',['representations'=>LegalRepresentation::where('status',true)->orderBy('city')->get()]);}
 public function consent(LegalRepresentation $representation){return view('representation::consent',compact('representation'));}
 public function storeConsent(Request $r,LegalRepresentation $representation){$r->validate(['contact_consent'=>'accepted']);$v=LegalRepresentationVolunteer::firstOrNew(['legal_representation_id'=>$representation->id,'user_id'=>Auth::id()]);$v->contact_consent=true;$v->save();if(!$v->notified_at){$u=$r->user();try{Mail::to($representation->email)->send(new TemplateMail('representation.volunteer-to-representative',['name'=>trim($u->name.' '.$u->surname),'email'=>$u->email,'phone'=>$u->phone_number,'city'=>$representation->city]));Mail::to($u->email)->send(new TemplateMail('representation.representative-to-volunteer',['name'=>trim($u->name.' '.$u->surname),'city'=>$representation->city,'representative'=>$representation->representative_name,'representative_email'=>$representation->email]));$v->update(['notified_at'=>now()]);}catch(\Throwable $e){report($e);}}$this->set_log('create',"{$representation->city} temsilciliği ile iletişim paylaşımı onaylandı.");return redirect()->route('representations.index')->with('success-status','İletişim bilgileriniz karşılıklı olarak paylaşıldı.');}
 public function candidateForm(){return view('representation::candidate',['representations'=>LegalRepresentation::where('status',true)->orderBy('city')->get()]);}
 public function storeCandidate(Request $r){$d=$r->validate(['legal_representation_id'=>'required|exists:legal_representations,id','is_lkd_member'=>'required|boolean','membership_number'=>'nullable|max:100','local_area'=>'required|max:255','motivation'=>'required|max:5000','community_experience'=>'nullable|max:5000','availability'=>'nullable|max:255','club_name'=>'nullable|max:255','contact_consent'=>'accepted']);LegalRepresentationCandidate::updateOrCreate(['legal_representation_id'=>$d['legal_representation_id'],'user_id'=>Auth::id(),'status'=>'pending'],$d);if($n=app(Organization::class)->notificationEmail())Mail::to($n)->send(new TemplateMail('representation.candidate',['name'=>trim($r->user()->name.' '.$r->user()->surname),'email'=>$r->user()->email,'city'=>LegalRepresentation::find($d['legal_representation_id'])?->city]));$this->set_log('create','Yasal temsilcilik adaylığı oluşturuldu.');return back()->with('success-status','Adaylığınız YK değerlendirmesine gönderildi.');}
 public function announcements(){ $rep=LegalRepresentation::where('user_id',Auth::id())->firstOrFail();return view('representation::announcements',['rep'=>$rep,'announcements'=>LegalRepresentationAnnouncement::where('legal_representation_id',$rep->id)->latest()->get()]);}
 public function storeAnnouncement(Request $r){$rep=LegalRepresentation::where('user_id',Auth::id())->firstOrFail();$d=$r->validate(['subject'=>'required|max:255','detail'=>'required|max:20000']);$a=LegalRepresentationAnnouncement::create(['legal_representation_id'=>$rep->id,'created_by'=>Auth::id(),'subject'=>$d['subject'],'detail'=>app(HtmlSanitizer::class)->sanitize($d['detail']),'status'=>$rep->can_send_announcements?'approved':'pending']);if($a->status==='approved')$this->send($a);elseif($n=app(Organization::class)->notificationEmail())Mail::to($n)->send(new TemplateMail('representation.announcement-pending',['subject'=>$a->subject,'city'=>$rep->city]));$this->set_log('create',"{$rep->city} duyurusu oluşturuldu.");return back()->with('success-status','Duyuru kaydedildi.');}
}
